<?php
declare(strict_types=1);namespace App\Application\Certificates;
use App\Application\{Audit\AuditWriter,Events\OutboxWriter,Shared\CanonicalJson};use App\Models\{CertificateTemplate,Policy,PolicyCertificate,StickerBatch,StickerStock,User};use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
final class CertificateService{public function __construct(private CanonicalJson$json,private AuditWriter$audit,private OutboxWriter$outbox){}public function createTemplate(array$d,User$actor):CertificateTemplate{return DB::transaction(function()use($d,$actor){DB::select('SELECT pg_advisory_xact_lock(hashtext(?))',['certificate-template:'.$d['code']]);$v=(CertificateTemplate::where('code',$d['code'])->max('version')??0)+1;return CertificateTemplate::create([...$d,'version'=>$v,'status'=>'DRAFT','template_hash'=>$this->json->hash($d['layout_schema']),'created_by'=>$actor->id]);});}public function approveTemplate(CertificateTemplate$t,User$actor):CertificateTemplate{return DB::transaction(function()use($t,$actor){$t=CertificateTemplate::whereKey($t->id)->lockForUpdate()->firstOrFail();if($t->status!=='DRAFT'||$t->created_by===$actor->id)throw ValidationException::withMessages(['actor'=>__('wave5.maker_checker')]);if($this->json->hash($t->layout_schema)!==$t->template_hash)throw ValidationException::withMessages(['layout_schema'=>__('wave5.template_changed')]);$latest=CertificateTemplate::where(['code'=>$t->code,'status'=>'ACTIVE'])->lockForUpdate()->latest('effective_from')->first();if($latest&&$t->effective_from->lessThanOrEqualTo($latest->effective_from))throw ValidationException::withMessages(['effective_from'=>__('wave5.template_effective_conflict')]);if($latest&&(!$latest->effective_until||$latest->effective_until->greaterThanOrEqualTo($t->effective_from)))$latest->update(['effective_until'=>$t->effective_from->copy()->subDay()]);$t->update(['status'=>'ACTIVE','approved_by'=>$actor->id,'approved_at'=>now()]);$this->audit->record('certificate.template.approved','certificate_template',$t->id,['version'=>$t->version]);return$t->refresh();});}public function receiveBatch(array$d,User$actor):StickerBatch{return DB::transaction(function()use($d,$actor){$b=StickerBatch::create([...$d,'quantity'=>count($d['stickers']),'received_by'=>$actor->id,'received_at'=>now(),'status'=>'RECEIVED']);foreach($d['stickers']as$s)StickerStock::create(['serial_number'=>$s['serial_number'],'carrier_id'=>$d['carrier_id'],'batch_number'=>$d['batch_number'],'status'=>'IN_STOCK','custodian_tenant_id'=>$d['custodian_tenant_id']??null,'sticker_batch_id'=>$b->id,'security_code_hash'=>hash('sha256',$s['security_code'])]);$this->audit->record('sticker.batch.received','sticker_batch',$b->id,['quantity'=>$b->quantity]);return$b;});}public function issue(Policy$p,CertificateTemplate$t,array$d,User$actor):array{return DB::transaction(function()use($p,$t,$d,$actor){$at=$p->coverage_starts_at;if($p->status!=='ACTIVE'||$t->status!=='ACTIVE'||$t->effective_from->greaterThan($at)||($t->effective_until&&$t->effective_until->lessThan($at)))throw ValidationException::withMessages(['status'=>__('wave5.active_policy_template_required')]);if(strlen($d['document_hash'])!==64||!ctype_xdigit($d['document_hash']))throw ValidationException::withMessages(['document_hash'=>__('wave5.document_hash_invalid')]);$token=Str::random(64);$c=PolicyCertificate::create(['policy_id'=>$p->id,'certificate_template_id'=>$t->id,'serial_number'=>$d['serial_number'],'verification_token_hash'=>hash('sha256',$token),'document_hash'=>strtolower($d['document_hash']),'status'=>'VALID','issued_at'=>now(),'issued_by'=>$actor->id]);if(isset($d['sticker_serial_number'])){$s=StickerStock::where(['serial_number'=>$d['sticker_serial_number'],'carrier_id'=>$p->carrier_id,'custodian_tenant_id'=>$p->tenant_id,'status'=>'IN_STOCK'])->lockForUpdate()->first();if(!$s)throw ValidationException::withMessages(['sticker_serial_number'=>__('wave5.sticker_unavailable')]);$s->update(['status'=>'ASSIGNED','assigned_policy_id'=>$p->id,'assigned_at'=>now()]);DB::table('sticker_custody_events')->insert(['id'=>(string)Str::uuid(),'sticker_stock_id'=>$s->id,'event_type'=>'ASSIGNED_TO_POLICY','from_tenant_id'=>$s->custodian_tenant_id,'to_tenant_id'=>$p->tenant_id,'actor_id'=>$actor->id,'reason_code'=>'POLICY_ISSUANCE','occurred_at'=>now()]);}$this->audit->record('certificate.issued','policy_certificate',$c->id,['policy_id'=>$p->id]);$this->outbox->record('certificate.issued','policy_certificate',$c->id,['certificate_id'=>$c->id,'policy_id'=>$p->id]);return['certificate'=>$c,'verification_token'=>$token];});}public function verify(string$serial,string$token,string$fingerprint):PolicyCertificate{$c=PolicyCertificate::with('policy')->where('serial_number',$serial)->first();$valid=$c&&hash_equals($c->verification_token_hash,hash('sha256',$token))&&$c->status==='VALID'&&$c->policy->status==='ACTIVE'&&!$c->policy->coverage_starts_at->isFuture()&&$c->policy->coverage_ends_at->isFuture();if($c)DB::table('certificate_verification_events')->insert(['id'=>(string)Str::uuid(),'policy_certificate_id'=>$c->id,'result'=>$valid?'VERIFIED':'REJECTED','request_fingerprint_hash'=>hash('sha256',$fingerprint),'occurred_at'=>now()]);if(!$valid)throw ValidationException::withMessages(['certificate'=>__('wave5.certificate_not_verified')]);return$c;}public function void(PolicyCertificate$c,string$reason,User$actor):PolicyCertificate{if($c->status!=='VALID')throw ValidationException::withMessages(['status'=>__('wave5.certificate_not_valid')]);$c->update(['status'=>'VOID','voided_at'=>now(),'voided_by'=>$actor->id,'void_reason'=>$reason]);$this->audit->record('certificate.voided','policy_certificate',$c->id,[],'CERTIFICATE_VOIDED');return$c->refresh();}}
